//! Opt-in local-binding and runtime string obfuscation.
//! Enable the `enabled` Cargo feature in your selected production build.
#![forbid(unsafe_code)]
extern crate self as rustveil;
pub use rustveil_macros::{obfuscate, veil_str};

#[doc(hidden)]
pub mod __private {
    /// Public only for code generated by the macro. Not a stable public API.
    #[inline(never)]
    pub fn decode(encoded: &[u8], seed: u64) -> String {
        let encoded = std::hint::black_box(encoded);
        let mut state = std::hint::black_box(seed);
        let bytes: Vec<u8> = encoded
            .iter()
            .map(|b| {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                *b ^ (state >> 56) as u8
            })
            .collect();
        // Macro encoding preserves valid UTF-8. Avoid unchecked conversion.
        String::from_utf8(bytes).expect("rustveil: invalid generated UTF-8")
    }
}
